// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(674000);

    const errors: Error[] = [];
    page.on('pageerror', err => errors.push(err));

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    // Wait for network activities to finish
    await page.waitForTimeout(5000);

    await page.goto(`${baseUrl}/`);
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');
    await page.getByTestId("main-menu-trigger").click();
    await expect(page.getByRole("radio", { name: "Dark mode - Shift+Alt+D" })).toContainText("Dark mode");
    await page.getByTestId("dropdown-menu").getByRole("radio", { name: "Dark mode - Shift+Alt+D" }).click();
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');
    await page.getByTestId("dropdown-menu").getByRole("radio", { name: "Light mode - Shift+Alt+D" }).click();
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');
    await page.getByTestId("dropdown-menu").getByRole("radio", { name: "System mode" }).click();
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'light');
    await expect(page.getByTestId("dropdown-menu").getByRole("radio", { name: "System mode" })).toBeChecked();

    expect(errors).toHaveLength(0);
});
